206			/* Check for partial packet */
207			if (skb->len < hci_skb_expect(skb))
208				continue;
209	
210			for (i = 0; i < pkts_count; i++) {
211				if (hci_skb_pkt_type(skb) == (&pkts[i])->type)
212					break;
213			}
