229					/* Single octet variable length */
230					dlen = skb->data[(&pkts[i])->loff];
231					hci_skb_expect(skb) += dlen;
232	
233					if (skb_tailroom(skb) < dlen) {
234						kfree_skb(skb);
235						return ERR_PTR(-EMSGSIZE);
236					}
237					break;
